const storeID = PaneLayout.#STORE_MAP.get(event.originalTarget.id);
if (!storeID) {
  return;
}

const splitter = event.target;
const dimension =
  splitter.resizeDirection == "vertical" ? "height" : "width";
XULStoreUtils.setValue(
  "messenger",
  storeID,
  dimension,
  splitter[dimension]
);
break;
